import test from 'node:test';
import assert from 'node:assert/strict';
import { getCustomer, listCustomers, validateCustomer, normalizeId } from '../src/customers.js';

test('normalizeId trims whitespace and uppercases', () => {
  assert.equal(normalizeId('c-003'), 'C-003');
  assert.equal(normalizeId('C-003 '), 'C-003');
  assert.equal(normalizeId(' c-003'), 'C-003');
  assert.equal(normalizeId(' c-003 '), 'C-003');
  assert.equal(normalizeId('c-003 '), 'C-003');
});

test('getCustomer finds a customer by id', () => {
  const r = getCustomer('C-003');
  assert.equal(r.ok, true);
  assert.equal(r.value.name, 'Kite & Co');
});

test('getCustomer accepts mixed case and whitespace', () => {
  assert.equal(getCustomer('c-003').ok, true);
  assert.equal(getCustomer('C-003 ').ok, true);
  assert.equal(getCustomer(' c-003').ok, true);
  assert.equal(getCustomer(' C-003 ').ok, true);
  assert.equal(getCustomer('c-003').value.name, 'Kite & Co');
  assert.equal(getCustomer('C-003 ').value.name, 'Kite & Co');
});

test('getCustomer reports an unknown id', () => {
  assert.deepEqual(getCustomer('C-999'), { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('every customer has a tier', () => {
  for (const c of listCustomers()) assert.ok(['gold', 'silver', 'standard'].includes(c.tier), c.id);
});

test('validateCustomer needs an id, a name and an email', () => {
  assert.equal(validateCustomer({ id: 'C-100', name: 'X', email: 'x@y.example' }).ok, true);
  assert.deepEqual(validateCustomer({ id: 'C-100', name: 'X', email: 'nope' }), { ok: false, error: 'CUSTOMER_INVALID' });
});

/** Every error code the project returns, with a one-line message. Codes are UPPER_SNAKE_CASE. */
export const ERRORS = {
  AMOUNT_INVALID: 'Amount must be a whole, positive number of cents.',
  CREDIT_TOO_HIGH: 'Credit amount cannot exceed the invoice total.',
  CUSTOMER_INVALID: 'A customer needs an id, a name and a valid email.',
  CUSTOMER_NOT_FOUND: 'No customer with that id.',
  DATE_INVALID: 'Issue date must be a valid date in YYYY-MM-DD format.',
  DISCOUNT_INVALID: 'Discount percent must be a number between 0 and 100.',
  LINE_NOT_FOUND: 'That SKU is not on this invoice.',
  NO_LINES: 'Invoice must have at least one line item.',
  NOT_DRAFT: 'Cannot edit an invoice that is not in draft status.',
  NOT_ISSUED: 'Payment can only be recorded for issued or partially paid invoices.',
  OVERPAYMENT: 'Payment amount exceeds the balance due.',
  QTY_INVALID: 'Line quantity must be a positive integer.',
  TERMS_INVALID: 'Payment terms must be NET14, NET30, or EOM.',
  UNKNOWN_SKU: 'No product with that SKU in the catalogue.',
  VOUCHER_EXISTS: 'This invoice already has a voucher applied.',
};

/**
 * The message for an error code.
 * @param {string} code
 * @returns {string}
 */
export function message(code) {
  return ERRORS[code] ?? 'Unknown error.';
}

